test('F02 stored math: original full14/full trial/body are replayed exactly and remain historical audit data', () => {
  for (const row of ORIGINAL.rows) {
    const m = storedMetadataMath.decodeSnapshot(row.metadata),
      t = storedTrialMath.decodeSnapshot(row.trial),
      b = storedBodyMath.decodeSnapshot(row.body);
    assert.equal(m.mode, 'legacy');
    assertJsonEqual(m.snapshot, row.metadata);
    assertJsonEqual(t.snapshot, row.trial);
    assertJsonEqual(b.snapshot, row.body);
    assertJsonEqual(storedTrialMath.decodeNativeSnapshot(row.metadata).snapshot, row.trial);
    assertJsonEqual(storedBodyMath.decodeCompact(row.raw).snapshot, row.body);
    assert.equal(Object.hasOwn(m.snapshot, 'statusFacts'), false);
  }
});
test('F02 stored math: original exact plans and all original raw hash bases are unchanged', () => {
  for (const row of ORIGINAL.rows.filter((r: any) => r.plans)) {
    const m = storedMetadataMath.decodeSnapshot(row.metadata),
      t = storedTrialMath.decodeSnapshot(row.trial),
      b = storedBodyMath.decodeSnapshot(row.body);
    const shared = {
      expectedSnapshotVersionHash: row.metadata.snapshotVersionHash,
      hashBasis: NATIVE_SHORT_HASH_BASES.snapshot,
      expectedState: 'draft' as const,
    };
    assertJsonEqual(
      storedMetadataMath.planUpdateV2(m, { ...shared, title: 'SYNTHETIC changed' }),
      row.plans.metadata,
    );
    assertJsonEqual(
      storedTrialMath.planUpdate(t, {
        ...shared,
        metadata: { trial: { action: 'set', beforeParagraph: 3 } },
      }),
      row.plans.trial,
    );
    assertJsonEqual(
      storedBodyMath.planUpdate(b, row.plans.body.expectation.writeRequest),
      row.plans.body,
    );
    const upload = storedCoverMath.createUploadIntent(m, {
      ...shared,
      asset: row.plans.coverUpload.asset,
    });
    assertJsonEqual(upload, row.plans.coverUpload);
    assertJsonEqual(
      storedCoverMath.planSave(m, upload, {
        picUri: 'synthetic/new-recommended',
        picUrl: 'synthetic:derived-new',
      }),
      row.plans.coverSave,
    );
    const modern = createNativeShortMetadataSnapshot(row.raw);
    for (const key of [
      'snapshotVersionHash',
      'catalogHash',
      'documentHash',
      'savedFieldsHash',
      'categorySelectionHash',
    ])
      assert.equal((modern as any)[key], row.metadata[key]);
    assertJsonEqual(modern.hashBases, row.metadata.hashBases);
  }
});
test('F02 stored math: contemporary correct draft plans equal original math without changing historical carriers', () => {
  const row = ORIGINAL.rows[0],
    m = createNativeShortMetadataSnapshot(row.raw),
    shared = {
      expectedSnapshotVersionHash: m.snapshotVersionHash,
      hashBasis: NATIVE_SHORT_HASH_BASES.snapshot,
      expectedState: 'draft' as const,
    };
  assertJsonEqual(
    planNativeShortMetadataUpdateV2(m, { ...shared, title: 'SYNTHETIC changed' }),
    row.plans.metadata,
  );
  assertJsonEqual(
    planNativeShortTrialUpdate(createNativeShortTrialSnapshot(m), {
      ...shared,
      metadata: { trial: { action: 'set', beforeParagraph: 3 } },
    }),
    row.plans.trial,
  );
  assertJsonEqual(
    planNativeShortBodyUpdate(
      createNativeShortBodySnapshot(m),
      row.plans.body.expectation.writeRequest,
    ),
    row.plans.body,
  );
  const upload = createNativeShortCoverUploadIntent(m, {
    ...shared,
    asset: row.plans.coverUpload.asset,
  });
  assertJsonEqual(upload, row.plans.coverUpload);
  assertJsonEqual(
    planNativeShortCoverSave(m, upload, {
      picUri: 'synthetic/new-recommended',
      picUrl: 'synthetic:derived-new',
    }),
    row.plans.coverSave,
  );
});
test('F02 stored math: old enum and freshly resolved publication truth stay distinct', () => {
  const conflict = ORIGINAL.rows[1],
    unproven = ORIGINAL.rows[2];
  assert.equal(storedMetadataMath.decodeSnapshot(conflict.metadata).snapshot.state, 'draft');
  assert.equal(resolveShortEditorStatus(conflict.raw.editData).resolvedState, 'unknown');
  assert.equal(storedMetadataMath.decodeSnapshot(unproven.metadata).snapshot.state, 'published');
  assert.equal(resolveShortEditorStatus(unproven.raw.editData).resolvedState, 'unknown');
  for (const row of [conflict, unproven])
    assert.throws(() =>
      planNativeShortMetadataUpdateV2(createNativeShortMetadataSnapshot(row.raw), {
        expectedSnapshotVersionHash: row.metadata.snapshotVersionHash,
        hashBasis: NATIVE_SHORT_HASH_BASES.snapshot,
        expectedState: 'draft',
        title: 'changed',
      }),
    );
});
test('F02 stored math: no malformed or partial modern marker falls back to legacy', () => {
  const row = ORIGINAL.rows[0];
  for (const facts of [
    undefined,
    null,
    {},
    resolveShortManagementLabels(['已发布']),
    { ...resolveShortEditorStatus(row.raw.editData), draftEditable: false },
  ]) {
    assert.throws(() => storedMetadataMath.decodeSnapshot({ ...row.metadata, statusFacts: facts }));
    assert.throws(() => storedBodyMath.decodeCompact({ ...row.raw, statusFacts: facts }));
  }
  assert.throws(() => storedMetadataMath.decodeSnapshot({ ...row.metadata, extra: true }));
  assert.throws(() => storedBodyMath.decodeCompact({ ...row.raw, extra: true }));
  assert.throws(() =>
    storedMetadataMath.planUpdateV2(
      { mode: 'modern', snapshot: row.metadata } as any,
      row.plans.metadata.expectation.request,
    ),
  );
});
test('F02 stored math: compact modern4 reconstructs full modern body while default sources reject old carriers', () => {
  const row = ORIGINAL.rows[0],
    m = createNativeShortMetadataSnapshot(row.raw),
    b = createNativeShortBodySnapshot(m),
    compact = { ...row.raw, statusFacts: m.statusFacts },
    decoded = storedBodyMath.decodeCompact(compact);
  assert.equal(decoded.mode, 'modern');
  assertJsonEqual(decoded.snapshot, b);
  assert.throws(() => createNativeShortTrialSnapshot(row.metadata));
  assert.throws(() => createNativeShortBodySnapshot(row.metadata));
  assert.throws(() => validateNativeShortBodySnapshot(row.body));
  assert.throws(() =>
    planNativeShortMetadataUpdateV2(row.metadata, {
      expectedSnapshotVersionHash: row.metadata.snapshotVersionHash,
      hashBasis: NATIVE_SHORT_HASH_BASES.snapshot,
      expectedState: 'draft',
      title: 'changed',
    }),
  );
});
test('F02 stored math: descriptor-first codec never invokes raw/facts getters or serializers', () => {
  let calls = 0;
  for (const path of ['state', 'statusFacts', 'editData']) {
    const value = structuredClone(ORIGINAL.rows[0].metadata);
    Object.defineProperty(value, path, {
      enumerable: true,
      get() {
        calls++;
        return null;
      },
    });
    assert.throws(() => storedMetadataMath.decodeSnapshot(value));
  }
  const compact = structuredClone(ORIGINAL.rows[0].raw);
  compact.toJSON = () => {
    calls++;
    return {};
  };
  assert.throws(() => storedBodyMath.decodeCompact(compact));
  assert.equal(calls, 0);
});

