function modernLater(kind: 'trial' | 'cover') {
  const row = OLD_GRAPHS[kind + 'Uncertain'],
    rc: any = structuredClone(row.reconciliation),
    read: any = structuredClone(rc.document.payload.result);
  read.snapshot = nativeFromOld(read.snapshot);
  const payload =
    kind === 'trial'
      ? trialProof.createNativeShortTrialReconciliationEvidence(
          read,
          rc.original,
          rc.document.payload.provenance,
        )
      : coverProof.createNativeShortCoverReconciliationEvidence(
          read,
          rc.original,
          rc.document.payload.provenance,
        );
  rc.document.payload = payload;
  rc.ref.sha256 = sha(canonicalJson(rc.document) + '\n');
  rc.manifest.evidence = [structuredClone(rc.ref)];
  rc.readJob.result = { manifest: rc.manifest };
  return rc;
}
test('F02 explicit old complete original plus independent modern later GET bridge authenticates both graphs', () => {
  for (const kind of ['trial', 'cover'] as const) {
    const original = OLD_GRAPHS[kind + 'Uncertain'],
      prior = JSON.stringify(original),
      rc = modernLater(kind);
    const checked =
      kind === 'trial'
        ? trialProof.validateNativeShortTrialReconciliationContext(rc)
        : coverProof.validateNativeShortCoverReconciliationContext(rc);
    assert.equal(checked.status, 'succeeded');
    assert.equal(checked.result.originalSaveAcknowledged, false);
    assert.equal(Object.keys(rc.document.payload.result.snapshot).length, 15);
    assert.equal(
      Object.keys(
        rc.original.documents[0].payload.held.nativeSnapshot ??
          rc.original.documents[0].payload.held.snapshot,
      ).length,
      14,
    );
    const projection =
      kind === 'trial'
        ? trialProof.projectNativeShortTrialReconciliationContext(rc)
        : coverProof.projectNativeShortCoverReconciliationContext(rc);
    assertObserved(projection, 'draft', 'later_read', rc.ref);
    assert.equal(JSON.stringify(original), prior);
    const broken: any = structuredClone(rc);
    broken.document.payload.result.snapshot.statusFacts = null;
    broken.ref.sha256 = sha(canonicalJson(broken.document) + '\n');
    broken.manifest.evidence = [structuredClone(broken.ref)];
    broken.readJob.result = { manifest: broken.manifest };
    assert.throws(() =>
      kind === 'trial'
        ? trialProof.validateNativeShortTrialReconciliationContext(broken)
        : coverProof.validateNativeShortCoverReconciliationContext(broken),
    );
  }
});
// Reseal physical refs, link hashes and the body prior-stage chain. A mixed-mode failure
// must come from the authenticated graph contract, not stale outer document bytes.
function reseal(context: any, body = false) {
  const byId = new Map(context.refs.map((r: any) => [r.id, r]));
  function links(value: any): void {
    if (!value || typeof value !== 'object') return;
    if (
      !Array.isArray(value) &&
      typeof value.id === 'string' &&
      Object.hasOwn(value, 'sha256') &&
      byId.has(value.id)
    ) {
      const ref: any = byId.get(value.id);
      value.sha256 = ref.sha256;
      value.capturedAt = ref.capturedAt;
    }
    for (const child of Object.values(value)) links(child);
  }
  for (let i = 0; i < context.documents.length; i++) {
    const document = context.documents[i];
    links(document);
    if (body && i > 0)
      document.payload.priorStageHash = bodyProof.nativeShortBodyGraphHash(
        context.documents[i - 1].payload,
      );
    context.refs[i].sha256 = sha(canonicalJson(document) + '\n');
  }
  links(context.attempts);
  links(context.job.result);
  if (context.job.status === 'succeeded')
    context.job.result = structuredClone(context.documents.at(-1).payload);
  return context;
}
test('F02 ordinary stored graphs reject mixed legacy/modern carriers even after full physical resealing', () => {
  const tc: any = structuredClone(OLD_GRAPHS.trialComplete.context),
    held = tc.documents.find((d: any) => d.dataset === 'short_native_trial_pre_save').payload.held;
  held.nativeSnapshot = nativeFromOld(held.nativeSnapshot);
  reseal(tc);
  for (let i = 0; i < tc.documents.length; i++)
    assert.equal(tc.refs[i].sha256, sha(canonicalJson(tc.documents[i]) + '\n'));
  assert.throws(() => trialProof.validateNativeShortTrialEvidenceContext(tc, 'complete'));
  const cc: any = structuredClone(OLD_GRAPHS.coverComplete.context),
    ch = cc.documents.find((d: any) => d.dataset === 'short_native_cover_pre_save').payload.held;
  ch.snapshot = nativeFromOld(ch.snapshot);
  reseal(cc);
  assert.throws(() => coverProof.validateNativeShortCoverEvidenceContext(cc, 'complete'));
  const bc: any = structuredClone(OLD_BODY.context),
    native = bc.documents.find((d: any) => d.dataset === 'short_native_body_pre_save').payload
      .payload.native;
  native.statusFacts = createNativeShortMetadataSnapshot(native).statusFacts;
  reseal(bc, true);
  for (let i = 0; i < bc.documents.length; i++)
    assert.equal(bc.refs[i].sha256, sha(canonicalJson(bc.documents[i]) + '\n'));
  assert.throws(() => bodyProof.validateNativeShortBodyEvidenceContext(bc, 'complete'));
});
